<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PhotoWorkflowFixtureIsolation.php';
use DigiForge\AI\{ProviderEvidenceRepository,ShopAiGovernanceRepository,ImageGenerationWireContract};
final class ImageProviderEvidenceTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_ai','manage_digiforge_pod']);global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 public function testObservedImageRequestIdAndRequestBoundModelAreNotInventedTextResponses():void {
  $repo=new ProviderEvidenceRepository();self::assertTrue(method_exists($repo,'recordImageOutcome'));$shop='personalized_pod';$gov=new ShopAiGovernanceRepository();self::assertNotWPError($gov->savePolicy(['shop_key'=>$shop,'currency'=>'USD','budgets'=>['run'=>'.02','day'=>'.03','month'=>'.04'],'stages'=>['render'=>['limit'=>3]]]));$request=hash('sha256','synthetic request');$money=new DigiForge\AI\MonetaryReservationRepository();self::assertNotWPError($money->reviewQuote($shop,json_encode(['provider'=>'openai','quote_id'=>'synthetic-'.wp_generate_uuid4(),'model'=>'gpt-image-1','request_sha256'=>$request,'currency'=>'USD','maximum_charge'=>'0.01','inclusive_all_charges'=>true,'valid_from'=>gmdate('Y-m-d\TH:i:s\Z',time()-10),'valid_until'=>gmdate('Y-m-d\TH:i:s\Z',time()+3600),'evidence_kind'=>'SYNTHETIC_TEST_ONLY']),'CONFIRM_PROVIDER_QUOTE'));$contract=$money->findQuote($shop,['model'=>'gpt-image-1','request_sha256'=>$request]);self::assertNotWPError($contract);$usage=$gov->reserveGeneration($shop,'render','synthetic-'.wp_generate_uuid4(),['run_id'=>'synthetic-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')],$contract);self::assertNotWPError($usage);
  $body=json_encode(['created'=>time(),'data'=>[['b64_json'=>'AA==']],'usage'=>['input_tokens'=>4,'output_tokens'=>3,'total_tokens'=>7,'input_tokens_details'=>['text_tokens'=>2,'image_tokens'=>2]]]);$result=$repo->recordImageOutcome((int)$usage['id'],$shop,'req_synthetic_image','gpt-image-1',$body,hash('sha256','synthetic request'),'OFFLINE_SIMULATOR');self::assertNotWPError($result);self::assertSame('req_synthetic_image',$result['response_id']);self::assertSame('IMAGE_HTTP_REQUEST_ID',$result['response_identity_kind']);self::assertSame('REQUEST_BOUND_IMAGE_MODEL',$result['model_evidence']);self::assertSame('OFFLINE_SIMULATOR',$result['observation_mode']);self::assertSame(7,$result['usage']['total_tokens']);self::assertSame(hash('sha256',$body),$result['provider_response_sha256']);self::assertWPError($repo->recordOutcome((int)$usage['id'],$shop,['response_id'=>'req_synthetic_image','model'=>'gpt-image-1','usage'=>['input_tokens'=>4,'output_tokens'=>3,'total_tokens'=>7]]));
  self::assertWPError($repo->settle((int)$usage['id'],$shop,[]),'A simulation must never become actual provider spend.');
 }
}
